using var stage = SystemChain.Empty
    .Add<LeakAndGcSystem>()
    .Add<OomKillerSystem>()
    .CreateStage(world);

var leaky = world.Create(HList.From(new Memory(0, 60, 12, 4)));

for (var tick = 1; leaky.IsValid && tick <= 8; tick++) {
    Console.WriteLine($"tick {tick}");
    stage.Tick();
}

public partial record struct Memory(
    [Sia] int Used, [Sia] int Limit, [Sia] int LeakRate, [Sia] int GcRate);

public class LeakAndGcSystem() : SystemBase(Matchers.Of<Memory>())
{
    public override void Execute(World world, IEntityQuery query)
    {
        foreach (var entity in query) {
            ref var mem = ref entity.Get<Memory>();
            if (mem.LeakRate > 0) {
                mem.Used += mem.LeakRate;
                Console.WriteLine($"leak: used={mem.Used}/{mem.Limit}");
            }
            if (mem.GcRate > 0 && mem.Used > 0) {
                mem.Used = Math.Max(mem.Used - mem.GcRate, 0);
                Console.WriteLine($"gc: reclaimed, used={mem.Used}");
            }
        }
    }
}

public class OomKillerSystem() : SystemBase(Matchers.Of<Memory>())
{
    private readonly List<Entity> _dead = [];

    public override void Execute(World world, IEntityQuery query)
    {
        foreach (var entity in query) {
            if (entity.Get<Memory>().Used >= entity.Get<Memory>().Limit) {
                _dead.Add(entity);
            }
        }
        foreach (var entity in _dead) {
            entity.Destroy();
            Console.WriteLine("oom-killer: process killed.");
        }
        _dead.Clear();
    }
}

using var stage = SystemChain.Empty.Add<AffinitySystem>().CreateStage(world);

var proc = world.Create(HList.From(new CoreAffinity(0)));
stage.Tick();

new CoreAffinity.View(proc, world) { Core = 7 };
stage.Tick();

public partial record struct CoreAffinity([Sia] int Core);

public class AffinitySystem() : SystemBase(
    Matchers.Of<CoreAffinity>(),
    EventUnion.Of<CoreAffinity.SetCore>())
{
    private const int HotCore = 7;

    public override void Execute(World world, IEntityQuery query)
    {
        foreach (var entity in query) {
            var core = entity.Get<CoreAffinity>().Core;
            Console.WriteLine(core == HotCore
                ? $"migrated onto contended core {HotCore}; cache-thrash tax applied."
                : $"scheduled on core {core}, no contention.");
        }
    }
}

using var stage = SystemChain.Empty.Add<SignalTermSystem>().CreateStage(world);

var stubborn = world.Create(HList.From(new Process("stubborn-service")));

world.Send(stubborn, Term.Instance);
world.Send(stubborn, HOEvents.Cancel<Term>.Instance);
stage.Tick();
Console.WriteLine(stubborn.IsValid
    ? "trapped SIGTERM and lives on."
    : "exited.");

if (stubborn.IsValid) {
    stubborn.Destroy();
}
Console.WriteLine(stubborn.IsValid
    ? "still alive?!"
    : "SIGKILL: gone for good — no handler can catch this one.");

public readonly record struct Process(string Name);

public sealed class Term : SingletonEvent<Term>, ICancellableEvent;

public class SignalTermSystem() : SystemBase(
    Matchers.Any,
    EventUnion.Of<Term>(),
    filter: EventUnion.Of<HOEvents.Cancel<Term>>())
{
    public override void Execute(World world, IEntityQuery query)
    {
        Console.WriteLine("delivering SIGTERM...");
        foreach (var entity in query) {
            var name = entity.Get<Process>().Name;
            entity.Destroy();
            Console.WriteLine($"[{name}] terminated gracefully.");
        }
    }
}

var nginx = world.Create(HList.From(new Combatant("nginx", 10, 6, 50)));
var cron = world.Create(HList.From(new Combatant("cron", 20, 3, 30)));

Signal(cron, nginx, world);
Signal(nginx, cron, world);

static void Signal(Entity attacker, Entity target, World world)
{
    ref readonly var atk = ref attacker.Get<Combatant>();
    ref readonly var def = ref target.Get<Combatant>();
    var damage = Math.Max(0, atk.Attack - def.Defense);
    var view = new Combatant.View(target, world);
    view.Privilege = Math.Max(0, view.Privilege - damage);
    Console.WriteLine($"{atk.Name} hits {def.Name} for {damage}; {def.Name} privilege now {view.Privilege}");
}

public partial record struct Combatant(
    [Sia] string Name, [Sia] int Attack, [Sia] int Defense, [Sia] int Privilege);
